function standby = mfun_smcvc_standby(enable, p)
%MFUN_SMCVC_STANDBY Block standby of the control system.
%   Generated by motulator_export from the MATLAB port of motulator and called by the
%   MATLAB Function block of the library of motulator, whose folder motulator.setup adds
%   to the MATLAB path. The parameters are the fields of the struct p (from the mask, []
%   as NaN). The state is in persistent variables, of which each MATLAB Function block
%   has its own copy.
persistent self
if isempty(self)
    self = struct('release_step', false);
end
% Standby while the gates are blocked and at the first sampling instant
% after the release of a sensorless drive
standby = double(enable <= 0 || self.release_step);
self.release_step = p.sensorless > 0 && enable <= 0;
end
